const pathFor = (file) => resolve(root, file);
const hashBuffer = (buffer) => createHash("sha256").update(buffer).digest("hex");
const exists = async (file) => {
  try { await access(pathFor(file)); return true; } catch { return false; }
};
const currentHash = async (file) => hashBuffer(await readFile(pathFor(file)));

async function isFinalState() {
  for (const [file, hash] of Object.entries(expectedFinal)) {
    if (!(await exists(file)) || (await currentHash(file)) !== hash) return false;
  }
  for (const file of deletedFiles) if (await exists(file)) return false;
  return true;
}

if (await isFinalState()) {
  console.log("✓ Entenarchiv 4.6.22 Hardening & Cleanup ist bereits vollständig angewendet. 0 Änderungen.");
  process.exit(0);
}

const mismatches = [];
for (const file of Object.keys(expectedFinal)) {
  if (addedFiles.has(file)) {
    if (await exists(file)) {
      const hash = await currentHash(file);
      if (hash !== expectedFinal[file]) mismatches.push(`${file}: neue 4.6.22-Datei existiert bereits mit anderem Inhalt`);
    }
    continue;
  }
  if (!(await exists(file))) { mismatches.push(`${file}: erwartete 4.6.21-Ausgangsdatei fehlt`); continue; }
  const hash = await currentHash(file);
  if (hash !== expectedSource[file] && hash !== expectedFinal[file]) {
    mismatches.push(`${file}: Ausgangsdatei weicht vom geprüften 4.6.21-Stand ab`);
  }
}
for (const file of deletedFiles) {
  if (!(await exists(file))) continue;
  const hash = await currentHash(file);
  if (hash !== expectedSource[file]) mismatches.push(`${file}: zu löschende Altdatei wurde seit 4.6.21 verändert`);
}
if (mismatches.length) {
  throw new Error(`Sicherheitsstopp vor der ersten Änderung:\n- ${mismatches.join("\n- ")}`);
}

let changed = 0;
for (const [file, encoded] of Object.entries(payload)) {
  const bytes = Buffer.from(encoded, "base64");
  const hash = hashBuffer(bytes);
  if (hash !== expectedFinal[file]) throw new Error(`Interner Payload-Fehler: ${file}`);
  if (await exists(file) && (await currentHash(file)) === hash) continue;
  await mkdir(dirname(pathFor(file)), { recursive: true });
  await writeFile(pathFor(file), bytes);
  changed += 1;
  console.log(`✓ ${file}`);
}
for (const file of deletedFiles) {
  if (!(await exists(file))) continue;
  await rm(pathFor(file));
  changed += 1;
  console.log(`✓ entfernt: ${file}`);
}

for (const [file, hash] of Object.entries(expectedFinal)) {
  if (!(await exists(file)) || (await currentHash(file)) !== hash) throw new Error(`Nachprüfung fehlgeschlagen: ${file}`);
}
for (const file of deletedFiles) if (await exists(file)) throw new Error(`Nachprüfung fehlgeschlagen: ${file} wurde nicht entfernt`);

console.log(`\n✓ 4.6.22 vollständig angewendet: ${changed} Dateiänderungen.`);
